def drive(me, enemy, arena):
    if not me.can_drive:
        return 0, 0

    front = me.weapons["front"]
    dist = distance_to(enemy.x, enemy.y)
    turn = bearing_to(enemy.x, enemy.y)

    if front["holding"]:
        return 0, 0

    if front["state"] == "closing":
        return 0.12, 0.12

    if front["state"] == "closed":
        return 0, 0

    if front["state"] == "open" and front["cooldown"] > 0:
        return 0, 0

    if dist <= 1.9:
        if abs(turn) < 25:
            return 0.12, 0.12
        if turn > 0:
            return 0.25, 1.0
        return 1.0, 0.25

    if abs(turn) > 15:
        if turn > 0:
            return 0.25, 1.0
        return 1.0, 0.25

    return 1.0, 1.0


def weapons(me, enemy, arena):
    front = me.weapons["front"]

    if not me.memory.get("spinner_started"):
        me.memory["spinner_started"] = 1
        return spin("back", 2500)

    if front["holding"]:
        return None

    if front["state"] == "closed":
        return release("front")

    if front["health"] <= 0:
        return None

    if front["state"] == "open" and front["cooldown"] <= 0:
        dist = distance_to(enemy.x, enemy.y)
        turn = bearing_to(enemy.x, enemy.y)
        if dist <= 1.9 and abs(turn) < 25:
            return grab("front")

    return None

def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    t = max(-1, min(1, b / 40.0))
    if d < 0.8:
        t = max(-0.4, min(0.4, b / 60.0))
    left = 1.0 - max(0.0, t)
    right = 1.0 + min(0.0, t)
    if b < 0:
        left = 1.0 + t
        right = 1.0 - min(0.0, t)
    if d > 1.5 and abs(b) > 100:
        left = -1.0
        right = -1.0
    return (left, right)

