def drive(me, enemy, arena):
    # attack the enemy's left flank (thin aluminium plate, weak wheel)
    h = radians(enemy.heading)
    tx = enemy.x - 0.55 * sin(h)
    ty = enemy.y + 0.55 * cos(h)
    b = bearing_to(tx, ty)
    d = distance_to(tx, ty)
    t = max(-1, min(1, b / 40.0))
    if d < 0.7:
        t = max(-0.3, min(0.3, b / 60.0))
    left = 1.0 - max(0.0, t)
    right = 1.0 + min(0.0, t)
    if b < 0:
        left = 1.0 + t
        right = 1.0 - min(0.0, t)
    if d > 1.5 and abs(b) > 100:
        left = -1.0
        right = -1.0
    # never sit still inside the clamp's reach
    if d < 1.2 and abs(b) < 20:
        left = max(left, 0.5)
        right = max(right, 0.5)
    return (left, right)

